import static org.mockito.Mockito.when;

public class UrlBuilderTest {

    @Test
    public void ofUrl() {
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        assertNotNull(builder.build());
    }

    @Test
    public void withoutPath() {
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        URI uri = ((URL) builder.build()).toURI();
        assertEquals("", uri.getPath());
    }

    @Test
    public void withPath() {
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com/path/to/resource"));
        URI uri = ((URL) builder.build()).toURI();
        assertEquals("/path/to/resource", uri.getPath());
    }

    @Test
    public void withoutQuery() {
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com/path/to/resource"));
        String query = ((URL) builder.build()).getQuery();
        assertNull(query);
    }

    @Test
    public void withQuery() {
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com/path/to/resource?query=string"));
        String query = ((URL) builder.build()).getQuery();
        assertEquals("query=string", query);
    }

    @Test
    public void appendKeyValStringKey() throws UnsupportedEncodingException {
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        builder.appendKeyVal(kv);
        String query = ((URL) builder.build()).getQuery();
        assertEquals("key=value", query);
    }

    @Test
    public void appendKeyValArrayKey() throws UnsupportedEncodingException {
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        Connection.KeyVal[] kv = new Connection.KeyVal[]{new Connection.KeyVal("k1", "v1"), new Connection.KeyVal("k2", "v2")};
        builder.appendKeyVal(kv);
        String query = ((URL) builder.build()).getQuery();
        assertEquals("k1=v1&k2=v2", query);
    }

    @Test
    public void appendKeyValNullKey() throws UnsupportedEncodingException {
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        Connection.KeyVal kv = new Connection.KeyVal(null, "value");
        buildUrlWithKeyVal(builder, kv);
    }

    @Test
    public void buildUrlWithMultipleQueryParams() throws UnsupportedEncodingException {
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        Connection.KeyVal[] kv = new Connection.KeyVal[]{new Connection.KeyVal("key1", "value1"), new Connection.KeyVal("key2", "value2")};
        buildUrlWithKeyVal(builder, kv);
    }

    private void buildUrlWithKeyVal(UrlBuilder builder, Connection.KeyVal kv) throws UnsupportedEncodingException {
        when(builder.appendKeyVal(Mockito.any(Connection.KeyVal.class))).thenReturn(null); // mock appendKeyVal to return null
        builder.appendKeyVal(kv);
        assertNotNull(builder.build());
    }
